/**
 * Serves the ISO Survey report page.
 *
 * The page is one self-contained HTML file per language, generated by the
 * design repo (bocetos/iso-survey-2025-correo/_build_v3.py → lib/informe/html).
 * The server only fills in who is looking: `__CONFIG__` becomes
 * { abierto, pais, api } and `__OTRO_URL__` the link to the other language.
 *
 * Public page (abierto: false): cover, the total and the guess with the form.
 * Personal page (abierto: true): the full report for the reader's country.
 */
import { readFileSync } from "node:fs";
import path from "node:path";
import type { Locale } from "./datos";

const cache = new Map<Locale, string>();

function template(locale: Locale): string {
  let html = cache.get(locale);
  if (!html) {
    html = readFileSync(path.join(process.cwd(), "lib", "informe", "html", `informe-${locale}.html`), "utf8");
    cache.set(locale, html);
  }
  return html;
}

export interface PageConfig {
  abierto: boolean;
  pais: string | null;
  otherLanguageUrl: string;
}

export const PUBLIC_PATH: Record<Locale, string> = { es: "/iso-survey", en: "/en/iso-survey" };
export const SUBMIT_PATH = "/api/informe/solicitar";

export function renderReportPage(locale: Locale, config: PageConfig): Response {
  const cfg = JSON.stringify({ abierto: config.abierto, pais: config.pais, api: SUBMIT_PATH })
    // Never let data close the inline <script>.
    .replace(/</g, "\\u003c");
  const html = template(locale)
    .replace("__CONFIG__", cfg)
    .replace("__OTRO_URL__", config.otherLanguageUrl);
  return new Response(html, {
    headers: {
      "Content-Type": "text/html; charset=utf-8",
      // Personal pages are private: keep them out of shared caches and search.
      "Cache-Control": config.abierto ? "private, no-store" : "public, max-age=300",
      ...(config.abierto ? { "X-Robots-Tag": "noindex, nofollow" } : {}),
      "Referrer-Policy": "strict-origin-when-cross-origin",
    },
  });
}
